@Component("recordsRepository-handler")
@ProcessingGroup("recordsRepository-processing-group")
public class RecordsRepositoryEventHandler {
	
	// core constructor
	RecordsRepositoryEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateRecordsRepositoryEvent
     */
    @EventHandler
    public void handle( CreateRecordsRepositoryEvent event) {
        entityManager.persist(new RecordsRepository(event.getRecordsRepositoryId(), event.getName(), event.getLocation(), event.getOwnerDepartment(), event.getOrganization(), event.getRecords(), event.getSystems(), event.getRetentionSchedules(), event.getLegalHolds(), event.getRepositoryType()));
    }

    /*
     * @param	event UpdateRecordsRepositoryEvent
     */
    @EventHandler
    public RecordsRepository handle( UpdateRecordsRepositoryEvent event) {
    	entityManager.merge(new RecordsRepository(event.getRecordsRepositoryId(), event.getName(), event.getLocation(), event.getOwnerDepartment(), event.getOrganization(), event.getRecords(), event.getSystems(), event.getRetentionSchedules(), event.getLegalHolds(), event.getRepositoryType()));
    }
    
    /*
     * @param	event DeleteRecordsRepositoryEvent
     */
    @EventHandler
    public void on( DeleteRecordsRepositoryEvent event) {
    	RecordsRepository entity = new RecordsRepository();
   
    	// ------------------------------------------
    	// apply the RecordsRepositoryId
    	// ------------------------------------------
    	entity.setRecordsRepositoryId( event.getRecordsRepositoryId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final RecordsRepositoryRepository recordsRepositoryEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(RecordsRepositoryEventHandler.class.getName());

}
